    'al.opt.on.ok': 'Publié, la page est en ligne.', 'al.opt.off.ok': 'Désactivé, la page a disparu du site.',
    'al.opt.dpa.d': 'Optionnel. Le contrat de l’article 28 pour les cas où un utilisateur est responsable du traitement et où nous ne faisons qu’exécuter : dépôts hébergés, acheteurs d’une marketplace, équipes, journaux du bot Discord. Désactivé par défaut : ne le proposez que si vous entendez en être tenu. Tant qu’il est désactivé, la page est inaccessible, elle n’est pas listée, la politique de confidentialité n’y renvoie pas, et personne n’est invité à l’accepter.',
