    'ami.sec.lead': 'Ce signalement se lit ici et nulle part ailleurs.',
    'ami.sec.body': 'Un signalement de sécurité peut décrire une attaque qui fonctionne : par où elle passe, le compte qu’elle a touché, les données qu’elle a atteintes. Il n’est donc jamais recopié sur Discord, jamais transporté dans l’alerte qui t’a prévenu, et jamais affiché dans la liste à côté. Il vit dans ce panneau, qu’aucune session n’atteint sans second facteur. Une réponse ne contient que ce que tu écris et ne recite jamais le signalement, parce qu’elle part par e-mail et que l’e-mail n’a pas de second facteur.',
    'ami.legal.lead': 'Celui-ci a une horloge.',
    'ami.legal.body': 'Le DSA attend une action sans retard injustifié, et sous la LCEN une notification en bonne et due forme est ce qui nous rend légalement présumés connaître. Réponds avec un motif dans les deux cas : un retrait comme un refus en demandent un. Une copie ou un effacement de données a un délai d’un mois à compter du jour d’arrivée, qui est la date ci-dessus.',
