    'ami.del.q': 'Supprimer ce message ?', 'ami.del.m': 'Le message, ses réponses et ses notes partent avec lui. C’est irréversible.',
    'ami.mp.title': 'Conversations entre membres',
    'ami.mp.lead': 'Ce réglage est un plafond. Chaque membre choisit ensuite pour lui-même.',
    'ami.mp.body': 'Désactivé, personne ne peut ouvrir une conversation avec un membre, quelle que soit la préférence de ce membre : une préférence peut refuser ce que le site autorise, jamais accorder ce que le site refuse. Cela ne concerne que les conversations adressées à une PERSONNE. Un dépôt, un catalogue et une équipe sont des choses publiées par quelqu’un, qui doivent rester joignables : rien sur cette carte ne les touche.',
