    'ami.mp.fate': 'Une conversation déjà ouverte reste lisible des deux côtés. Gelée veut dire que personne ne peut y ajouter ; l’horloge d’archivage et les réglages sont lus au moment où quelqu’un essaie d’écrire, donc réactiver restitue exactement ce qui était là au lieu de le réparer. Une conversation archivée n’est pas close non plus : chaque partie peut la rouvrir. Il n’y a pas de limite au nombre de conversations d’un membre ; les limites par heure et par jour arrêtent les rafales, et les réponses sont limitées par le réglage Réponses / heure plus bas.',

