    'hosting.cmp.paid.1': 'Tout ce qu’il y a dans le plan gratuit',
    'hosting.cmp.paid.2': 'Plusieurs dépôts et des catalogues dans le même espace',
    'hosting.cmp.paid.3': 'Tu envoies plus vite',
    'hosting.cmp.paid.4': 'Les boosts, l’offre à quelqu’un, et un terme long moins cher',
    'hosting.faq.eyebrow': 'Avant que tu demandes',
    'hosting.faq.title': 'Les questions qu’on reçoit vraiment',
    'hosting.faq.sub': 'À commencer par celle qu’une page de tarifs évite d’habitude.',
    'hosting.faq.q1': 'Il se passe quoi si j’arrête de payer ?',
    'hosting.faq.a1': 'Rien n’est supprimé à la seconde où le terme se termine. Ton contenu passe en lecture seule pendant un délai : il reste où il est, tu peux encore en récupérer une copie ou le transférer à un autre compte, et si tu renouvelles tout repart comme avant. Ce n’est qu’après ce délai que ça part pour de bon.',
    'hosting.faq.q2': 'Je peux changer de taille plus tard ?',
    'hosting.faq.a2': 'Oui, dans les deux sens, et le gratuit reste déduit : tu ne paies que ce qui dépasse. Le dépôt garde son adresse, donc rien de ce que tu as partagé ne s’arrête de marcher.',
    'hosting.faq.q3': 'Dépôt ou catalogue, il me faut lequel ?',
    'hosting.faq.a3': 'Un dépôt, ce sont les FICHIERS, à une adresse fixe depuis laquelle quelque chose vient les chercher. Un catalogue, c’est une LISTE que les gens parcourent et depuis laquelle ils installent. Tu publies ton propre travail ? Plutôt un dépôt. Tu rassembles celui des autres ? Plutôt un catalogue. Un pool tient les deux, donc tu n’as pas à trancher tout de suite.',
    'hosting.faq.q4': 'Plusieurs dépôts dans un seul pool ?',
    'hosting.faq.a4': 'C’est tout l’intérêt. Tu achètes de la place, pas un emplacement : mets-y un gros dépôt ou douze petits, et change d’avis après.',
    'hosting.faq.q5': 'Vous hébergez mon site ou mon bot Discord ?',
    'hosting.faq.a5': 'Pas aujourd’hui : ici on vend du stockage, pas un endroit où faire tourner du code. Demande quand même par la dernière carte de cette page. Si assez de monde le demande, c’est comme ça qu’on le saura.',
    'hosting.faq.q6': 'Et si tout est complet ?',
    'hosting.faq.a6': 'Tu peux laisser ton nom et la taille que tu visais, et être prévenu quand ça se libère. Le pool gratuit et le disque payant sont comptés séparément, donc l’un peut être plein pendant que l’autre a de la place.',
    'hosting.talk.eyebrow': 'Toujours pas ça ?',
    'hosting.talk.h': 'Alors dis-nous ce qu’il te faut',
    'hosting.talk.h.sub': 'Trois portes, pour que ce que tu écris arrive chez quelqu’un qui peut y répondre.',
    'hosting.termbar.t': 'Tu veux payer combien de temps d’avance ?',
    'hosting.termbar.s': 'Tous les prix ci-dessous suivent ce choix. Plus le terme est long, moins le mois coûte, et rien ne se renouvelle tout seul tant que tu ne l’actives pas.',
    'hosting.sizes.t': 'Les pools tout prêts',
    'hosting.sizes.s': 'Ce sont celles qu’on nous demande le plus. Si aucune ne te convient, le curseur est juste en dessous.',
    'hosting.boost.t': 'Tu héberges déjà quelque chose ici ?',
    'hosting.boost.s': 'Mets-le devant plus de monde pendant quelques jours. Une fois, facturé au jour, dans le même panier.',
    'hosting.freeplan.soldout.d': 'La réserve gratuite est entièrement prise pour l’instant. Elle est comptée à part, donc les tailles payantes ci-dessous n’y changent rien. Laisse ton nom et on te prévient dès qu’une place se libère.',
    'repos.addwhat.title': 'Ajouter un dépôt',
    'repos.addwhat.sub': 'Deux choses différentes, et ça vaut le coup de savoir laquelle tu veux.',
    'repos.addwhat.host': 'Héberge-le ici',
    'repos.addwhat.host.d': 'On garde les fichiers et on les sert. Tu obtiens une adresse qui ne bouge pas, un vrai compteur de téléchargements, et de quoi gérer les accès.',
    'repos.addwhat.pick': 'Dans quel pool ?',
    'repos.addwhat.left': 'libres',
    'repos.addwhat.full': 'Tes pools sont pleins, prends-en un plus grand, ou fais d’abord de la place.',
    'repos.addwhat.nopool': 'Tu n’as pas encore d’espace ici. Choisis une taille et elle arrive tout de suite dans cette page.',
    'repos.addwhat.more': 'Prendre plus de place',
    'repos.addwhat.get': 'Voir les formules',
    'repos.addwhat.ext': 'J’en ai déjà un ailleurs',
    'repos.addwhat.ext.d': 'Il est déjà en ligne quelque part : ton propre serveur, un hébergeur, une autre plateforme. Tu donnes l’adresse ; on n’en garde que la fiche, pas les fichiers.',
    'repos.addwhat.ext.go': 'Renseigner l’adresse',
    'repos.addwhat.ext.note': 'Rien n’est copié chez nous : si ton serveur tombe, le dépôt tombe avec.',
    'adm.plans.freedup': 'Il y a déjà une formule gratuite active (« {n} »). Modifie celle-là, ou désactive-la avant d’en créer une autre. La page publique n’en montre qu’une.',
    'hosting.x.title2': 'Trois mots, une bonne fois',
    'hosting.x.sub2': 'Le reste de la page suppose que tu les as dans le bon sens.',
    'hosting.diag.note2': 'Tu achètes de la place, pas un emplacement.',
    'hosting.cmp.free.4b': 'Un seul espace, et il est petit',
    'rd.tab.agent': 'Serveur',
    'rd.agent.t': 'Ton serveur, qui nous parle',
    'rd.agent.s': 'Ce dépôt vit sur une machine à toi. Plutôt que d’avoir une clé chez nous (ce qui mettrait ton serveur dans nos fuites à nous), c’est ta machine qui garde un jeton pour nous : elle appelle régulièrement pour dire qu’elle est vivante et ce qu’elle sert, et récupère ce que tu mets en file ci-dessous. On n’obtient jamais d’accès chez toi.',
    'rd.agent.new': 'Copie-le maintenant, il ne sera plus affiché',
    'rd.agent.snip': 'Un battement de cœur, c’est un seul appel. Mets ça sur une minuterie sur ton serveur :',
    'rd.agent.none': 'Pas encore de jeton. En créer un ne fait rien tout seul, rien ne se passe tant que ton serveur ne s’en sert pas.',
    'rd.agent.revoked': 'Le dernier jeton a été révoqué. Crées-en un nouveau quand le serveur est prêt à l’utiliser.',
