    'rd.listing': 'Servir un index du dossier',
    'rd.listing.d': 'Activé, parcourir un dossier montre la liste de ce qu’il contient, dans le même format qu’un simple serveur de fichiers : c’est ainsi qu’un client peut se synchroniser sans tout télécharger. Désactivé, les dossiers répondent 404 et chaque fichier reste téléchargeable à son adresse.',
