    'hosting.diag.note3': 'Un seul espace, et c’est toi qui décides comment le découper. À tout moment.',
    'hosting.termbar.t2': 'Payé d’avance pour',
    'hosting.termbar.s2': 'Définit tous les prix ci-dessous. Rien ne se renouvelle tout seul.',
    'hosting.termbar.full': 'plein tarif',
    'hosting.cmp.none.0': 'Tu gardes la main sur tout, et ça ne coûte rien de plus si la machine est déjà là',
    'hosting.cmp.none.1b': 'Le jour où tu changes de serveur, l’adresse change et tout ce qui pointait dessus casse',
    'hosting.cmp.none.5': 'Et personne ne te trouve ici : pas de page, pas de recherche, aucun catalogue ne te reprend',
    'hosting.cmp.free.5': 'Une page publique, la recherche, les favoris, on te trouve',
    'hosting.cmp.paid.5': 'Ton propre nom de domaine sur un dépôt ou un catalogue',
    'hosting.cmp.paid.6': 'La taille que tu veux, modifiable quand tu veux',
    'hosting.faq.q2b': 'Je peux passer à plus grand ensuite ? Ou à plus petit ?',
    'hosting.faq.q8': 'Un boost, ça fait quoi exactement ?', 'hosting.faq.a8': 'Il place ton dépôt ou ton catalogue en tête des listes publiques pour le nombre de jours qu’il porte, au-dessus de tout ce qui n’est pas boosté. Entre deux boostés, celui dont la fin est la plus lointaine passe devant : un boost plus long l’emporte sur un plus court. Ils se cumulent au lieu de se remplacer : en poser un sur quelque chose de déjà en vedette prolonge la fin au lieu de la redémarrer, donc pas de trou et rien de perdu. Quand il se termine, l’entrée reprend simplement sa place normale, et rien d’autre ne change.',
    'hosting.faq.q3b': 'C’est quoi la différence entre un dépôt et un catalogue ?',
    'hosting.faq.q4b': 'Je peux mettre plusieurs dépôts dans un seul pool ?',
    'hosting.faq.q5b': 'Vous pouvez héberger mon site, ou mon bot Discord ?',
    'hosting.faq.q7': 'Je peux utiliser mon propre domaine ?',
    'hosting.faq.a7': 'Oui, avec un pool payant. Tu fais pointer un sous-domaine chez nous, tu l’ajoutes au dépôt ou au catalogue, et on le sert dès que le DNS répond. Le plan gratuit, lui, garde son adresse bettercommunity.',
