    'dom.notyet': 'Pas encore. Un changement DNS met du temps à se propager ; l’enregistrement doit être lisible depuis l’internet public pour que ça passe.',
    'dom.cert': 'Le certificat est obtenu à la première visite de ce nom : la toute première requête peut donc prendre quelques secondes.',
    'dom.wait': 'Rien n’est servi sur ce nom tant que la vérification n’est pas passée. Un changement DNS met d’une minute à quelques heures à voyager.',
    'dom.del': 'Retirer ce domaine',
    'dom.del.m': 'Il cesse immédiatement d’être servi sur ce nom. L’adresse bettercommunity continue de marcher, comme depuis le début.',
    'dom.del.ok': 'Retirer',
