    'dom.gate.free': 'Servir ton propre nom veut dire obtenir et renouveler un certificat pour lui : ça vient donc avec les pools payants. Le plan gratuit garde son adresse bettercommunity.',
    'dom.gate.nopool': 'Ce n’est pas encore dans un pool de stockage, donc il n’y a rien ici vers quoi un domaine pourrait pointer.',
