    // Descriptions des champs
    'hs.d.hosting.totalCapacityGB': 'Le plafond global de tout ce que l’hébergement consomme, vérifié contre le disque réel à l’enregistrement.',
    'hs.d.hosting.reservedFreeGB': 'Toujours gardée libre sous la capacité totale, comme tampon de sécurité.',
    'hs.d.hosting.tempMarginGB': 'Pool distinct pour les soumissions au catalogue en attente de modération, plein = nouveaux envois refusés jusqu’à revue.',
    'hs.d.hosting.freeTierCapEnabled': 'Activé, le plan d’hébergement gratuit devient « complet » dès que les repos gratuits atteignent ensemble le plafond ci-dessous. Les plans payants n’y comptent jamais.',
    'hs.d.hosting.freeTierCapGB': 'Stockage total que le plan gratuit peut occuper au maximum, tous utilisateurs confondus, une fois l’option ci-dessus activée.',
    'hs.d.catalog.freeTierCapEnabled': 'Activé, l’hébergement gratuit des fichiers du catalogue devient « complet » dès que les envois gratuits atteignent ensemble le plafond ci-dessous. Les envois payants n’y comptent jamais.',
    'hs.d.catalog.freeTierCapMB': 'Octets de charge utile que le palier catalogue gratuit peut occuper au maximum, tous utilisateurs confondus, une fois l’option ci-dessus activée.',
    'hs.d.telemetry.storageLimitGB': 'Stockage autorisé à la base de télémétrie BMM (séparée), affiché comme utilisé vs alloué dans la capacité totale ci-dessus. 0 = non suivi.',
    'hs.d.analytics.maxMB': "Plafond de taille combinée pour les analytics du site : pages vues, interactions, vitals et replays de session. Une fois dépassé, les données les plus anciennes sont élaguées (replays les plus lourds d'abord) à chaque passage. S'ajoute à la rétention par durée sur l'écran Analytics. 0 = aucun plafond.",
    'hs.d.hosting.maxUploadMbps': 'Plafond strict sur la bande passante d’envoi qu’un seul repo peut demander (plans sur mesure + upgrades). La rareté peut l’abaisser quand la capacité se remplit. Défaut 1000.',
    'hs.d.hosting.maxCpuShare': 'Plafond strict sur la part de CPU qu’un seul repo peut demander. La rareté peut l’abaisser quand la capacité se remplit. Défaut 8.',
    'hs.d.hosting.burstFactor': 'Partage intelligent : quand le serveur est calme, un téléchargement de repo peut monter jusqu’à son plafond × ce facteur, en empruntant la capacité inactive. Se resserre au plafond sous charge. 1 = pas de burst. Défaut 4.',
    'hs.d.hosting.burstUntilActive': 'Le burst n’est autorisé que tant que moins de ce nombre de téléchargements sont en cours ; au-delà, chaque repo est tenu à son propre plafond. Défaut 3.',
    'hs.d.blog.maxTotalPosts': 'Plafond strict sur le nombre d’articles de blog du site entier. 0 = illimité. Les nouveaux articles sont refusés une fois atteint.',
    'hs.d.blog.maxTotalKB': 'Plafond strict sur la taille combinée de tous les corps d’articles (EN + FR). Appliqué à la création ET aux modifications qui font grossir un article. 0 = illimité.',
    'hs.d.docs.maxTotalPages': 'Plafond strict sur le nombre de pages de documentation. 0 = illimité. Les nouvelles pages sont refusées une fois atteint.',
    'hs.d.docs.maxTotalKB': 'Plafond strict sur la taille combinée de toutes les pages de docs (EN + FR). Appliqué à la création ET aux modifications qui font grossir une page. 0 = illimité.',
    'hs.d.history.maxRevisions': 'Combien d’anciens instantanés chaque article de blog / page de docs conserve avant que le plus ancien soit écrasé. Défaut 30.',
    'hs.d.history.maxRevisionKB': 'Plafonne aussi l’historique stocké de chaque élément par la taille : les instantanés les plus anciens sont supprimés une fois dépassé. 0 = pas de limite de taille (nombre seulement).',
    'hs.d.audit.maxDays': 'Les entrées du journal d’actions du staff plus anciennes que ceci sont purgées. 0 = conserver indéfiniment. Le journal est chaîné par HMAC (inviolable) : la purge est la seule suppression autorisée.',
    'hs.d.audit.maxEntries': 'Plafonne aussi le journal d’actions du staff par nombre d’entrées, les plus anciennes sont purgées au-delà. 0 = pas de plafond de nombre.',
    'hs.d.pricing.perGBCents': 'Coût d’hébergement de base, avant le multiplicateur de rareté. Ne s’applique qu’au-dessus du seuil gratuit ci-dessous.',
    'hs.d.pricing.hostingFreeGB': 'Les N premiers de stockage de chaque repo ne coûtent rien, les petits repos personnels sont gratuits. Seul le surplus est facturé.',
    'hs.d.pricing.perUploadMbpsCents': 'Coût par Mbps de bande passante d’envoi allouée à un repo.',
    'hs.d.pricing.perCpuShareCents': 'Coût par part de vCPU allouée à un repo.',
    'hs.d.pricing.featurePerDayCents': 'Coût pour garder un repo mis en avant sur la liste publique.',
    'hs.d.pricing.catalogHostPerMBCents': 'Facturé aux soumetteurs non-staff pour les charges utiles hébergées par nous au-dessus du seuil gratuit ci-dessous.',
    'hs.d.pricing.catalogFreeMB': 'Les N premiers de chaque soumission (app/plugin/thème/preset) sont gratuits, seul le surplus est facturé.',
    'hs.d.features.hostingEnabled': 'Désactive toute la fonctionnalité d’hébergement Server-Repo à l’échelle du site quand décoché.',

