    'rl.src.open': "Open source", 'rl.src.closed': "Closed source",
    'rl.license': "Licence", 'rl.license.h': "p. ex. MIT, GPL-3.0, Apache-2.0.",
    'rl.own': "Votre lien avec le projet",
    'rl.own.owner': "C’est mon projet", 'rl.own.fan': "Un projet que j’apprécie (pas le mien)",
    'rl.closed.note': "Nous référençons aussi les projets closed-source, mais uniquement à la demande de l’ayant droit, et avec une preuve de droits (licence, facture, déclaration signée). Votre document est stocké de façon privée, visible uniquement par le personnel d’examen, et supprimé une fois la décision prise.",
    'rl.proof.replace': "Remplacer la preuve", 'rl.proof.add': "Joindre une preuve de droits",
    'rl.est.free': "Délai habituel : {r}", 'rl.est.paid': "payant (prioritaire) : {r}",
    'rl.est.note': "Une estimation, d’après le nombre de demandes en attente actuellement ({n} en file), pas une promesse. Payer vous fait monter dans la file mais ne garantit pas de délai : vous pouvez toujours attendre.",
    'rl.tos.pre': "J’ai lu et j’accepte les", 'rl.tos.link': "Conditions de soumission", 'rl.tos.post': ", et je confirme que mes déclarations ci-dessus sont exactes.",
    'rl.pay.ack': "Je comprends que des frais d’examen payants sont NON REMBOURSABLES : ils achètent une place dans la file et une priorité, pas une inscription ni un délai garanti.",
    'rl.signin.short': "Connectez-vous pour soumettre, nous devons pouvoir vous répondre.",
    'rl.toomany': "Vous avez déjà le nombre maximum de demandes en attente de réponse.",
    'rl.nopay': "Les paiements sont indisponibles pour l'instant, votre demande a été enregistrée, non payée.",
    'rl.fail': "Impossible d'envoyer cela.",
    'hs.l.hosting.graceLapseHours': "Délai après la fin d'un terme (heures)",
    'hs.d.hosting.graceLapseHours': "Un terme d'hébergement terminé, ou un abonnement annulé, suspend le contenu au lieu de le supprimer, et voici le temps dont la personne dispose avant qu'il SOIT supprimé. Suspendu veut dire lecture seule, pas disparu : le propriétaire peut encore télécharger une copie, la transférer à un autre compte, ou renouveler et tout retrouve sa place. 72 = trois jours.",
    'hs.l.hosting.graceUnpaidHours': "Délai après un paiement ÉCHOUÉ (heures)",
    'hs.d.hosting.graceUnpaidHours': "La même fenêtre, pour le cas où la carte a échoué plutôt que la personne décidé. Plus long exprès : annuler est une décision, une carte expirée est un accident, et les mêmes trois jours punissent l'accident. Ça compte à partir du moment où Stripe cesse de réessayer, pas du premier échec. 168 = une semaine.",
    'hs.l.hosting.termMinMonths': 'Terme prépayé : minimum (mois)',
    'hs.d.hosting.termMinMonths': "Le terme le plus court qu'un paiement d'hébergement accepte. Le curseur de la page Hébergement va d'ici au maximum ci-dessous ; tout ce qui sort de la plage est refusé par le serveur, quoi que la page ait envoyé. 1 = un mois. Par défaut 1.",
    'hs.l.hosting.termMaxMonths': 'Terme prépayé : maximum (mois)',
    'hs.d.hosting.termMaxMonths': "Le terme le plus long qu'on peut prépayer d'un coup, en mois. Au-delà de 12 mois c'est toujours un paiement unique (Stripe ne facture pas d'intervalle supérieur à un an), donc le renouvellement auto est indisponible au-dessus de 12 quoi que tu mettes ici. Plafond 120. Par défaut 36.",
    'hs.l.hosting.termStepMonths': 'Terme prépayé : pas (mois)',
    'hs.d.hosting.termStepMonths': "Le curseur avance de ce nombre de mois, compté depuis le minimum : min 1 / pas 3 vend 1, 4, 7… ; min 3 / pas 3 vend 3, 6, 9…. Les paliers de remise (3, 6, 12, 24 mois et plus) s'appliquent à ce qui tombe sur la grille. Par défaut 1.",
    'hs.l.hosting.warnBeforeHours': "Prévenir combien de temps avant la fin (heures)",
    'hs.d.hosting.warnBeforeHours': "À quelle distance de l'échéance part l'avis « votre hébergement expire bientôt ». Mettre le délai de grâce au-dessus de celui-ci, c'est annoncer l'échéance quand elle est déjà la seule chose qui reste. Garde-le au moins aussi long que le préavis que tu veux leur laisser.",
    'hs.l.showcase.requestsEnabled': "Accepter les demandes d'inscription (gratuit)",
    'hs.d.showcase.requestsEnabled': "Affiche un formulaire « Proposer votre projet » sur /projects. Désactivé, le formulaire n'est pas proposé et la route refuse : une boîte à propositions sur un site dont le propriétaire ne lit pas les propositions est pire que pas de boîte. Chaque demande reste examinée ici avant que quoi que ce soit n'apparaisse.",
    'hs.l.showcase.paidEnabled': "Accepter les demandes PAYANTES",
    'hs.d.showcase.paidEnabled': "Ajoute une option payante à côté de la gratuite (ou à sa place, si la gratuite est désactivée). Payer achète une place dans la file d'examen et RIEN d'autre : la réponse reste la vôtre, et une demande payée refusée peut appeler un remboursement.",
    'hs.l.showcase.priceCents': "Prix de la demande payante (centimes)",
    'hs.d.showcase.priceCents': "Ce que facture l'option payante, une seule fois, dans la devise ci-dessous. 2000 = 20,00.",
    'hs.l.showcase.currency': "Devise de la demande payante",
    'hs.d.showcase.currency': "Code à trois lettres, en minuscules, usd, eur, chf. Doit être accepté par Stripe pour votre compte.",
    'hs.l.showcase.maxOpenPerUser': "Demandes en attente max. par personne",
    'hs.d.showcase.maxOpenPerUser': "Combien de demandes non examinées un compte peut détenir à la fois. Quelqu'un qui peut en ouvrir cinquante peut ensevelir la file. 0 = sans limite.",
    'ogp.sub': "Ce que Discord, X et Slack affichent quand un lien est collé. Chaque page a déjà une carte construite à partir de ce qu'elle est (un article de blog utilise son propre titre et sa couverture), donc laissez un champ vide pour la conserver. Chemins exacts uniquement : pas de jokers, rien n'est couvert que vous n'ayez listé.",
    'ogp.more': "Une ligne ici n'est pas seulement la carte du lien collé : le même titre et la même description deviennent le titre d'onglet, la balise meta description qu'affiche un résultat de recherche, et les balises og et twitter. Santé SEO ci-dessus les relit par page clé, et son crayon modifie cette même liste. Après un changement, un moteur de recherche l'affiche à son prochain passage ; Discord et X gardent un moment leur propre cache d'une carte.",
    'ogp.add': "Ajouter une page",
    'ogp.none': "Aucune surcharge, chaque page utilise sa carte intégrée.",
    'ogp.badpath': "Chaque ligne a besoin d'un chemin commençant par /, par exemple /hosting.",
    'ogp.titleEn': "Titre (EN)",
    'ogp.titleFr': "Titre (FR)",
    'ogp.descEn': "Description (EN)",
