    // Les icônes du bot sur Discord (discord-emojis.jsx) : état par icône, script d'envoi, import.
    'em.title': 'Icônes sur Discord', 'em.sub': 'Le bot dessine chaque icône comme un emoji d’application. Voici celles que Discord a vraiment, et comment les ajouter toutes d’un coup.',
    'em.refresh': 'Actualiser', 'em.copy': 'Copier', 'em.copied': 'Copié.',
