    'em.never': 'Pas encore de carte : chaque icône apparaît manquante tant que le script n’a pas tourné ou qu’aucune carte n’est importée.',
    'em.step1': 'Ajouter toutes les icônes d’un coup',
    'em.step1.d': 'Sur la machine qui fait tourner le bot, avec son jeton dans l’environnement. D’abord un essai, qui affiche seulement ce qu’il ferait :',
    'em.step1.d2': 'Puis le vrai passage. Il envoie ce qui manque, saute ce qui est déjà là, écrit app-emojis.json et envoie la carte à cette page :',
    'em.env.s': 'Il lit DISCORD_TOKEN, BCWEB_API_URL et BOT_SHARED_SECRET dans l’environnement.',
    'em.env.d': 'Le jeton sert uniquement à parler à Discord : il n’est jamais affiché ni envoyé au site. --prune supprime aussi les anciens dessins de nos propres icônes ; les emojis qui ne sont pas les nôtres ne sont jamais touchés. Si le site est injoignable, importe app-emojis.json ci-dessous.',
