    'hp.custom': 'Sections personnalisées', 'hp.custom.d': 'Tes propres blocs, écrits en Markdown, affichés en plus des blocs intégrés. Réordonne-les, active/désactive chacun, et choisis où il se place. Un FR vide retombe sur l’EN.',
    'hp.custom.top': 'Sous le hero', 'hp.custom.bottom': 'Au-dessus du soutien', 'hp.custom.on': 'Affiché',
