    'hp.textmoved': 'Pour modifier les textes de cette page (en anglais, en français ou dans une autre langue), utilise l’éditeur de Langues. Il modifie chaque chaîne du site, s’applique en direct, et revient au texte livré quand tu vides un champ.',
    'hp.v1': 'La longue',
    'hp.wire.hero': 'ACCUEIL',
    'hp.wire.none': 'aucune section',
    'hp.wire.count': '{n} section(s)',
    'hp.v1.s': 'Hero, pourquoi, comment ça marche, le hub dev, les commandes, les avis, les actus. Pour quelqu’un qui n’en a jamais entendu parler.',
    'hp.v2': 'Un seul écran',
    'hp.v2.s': 'Ni récit ni défilement avant la réponse : les produits en liste, le média à côté, les actus à la fin. Pour quelqu’un venu chercher quelque chose.',
    'hp.v3': 'Ce qui se passe',
    'hp.v3.s': 'Un fil, articles, sondage en cours, ce qu’on en dit, ce qui est proposé. Pas de hero. Pour quelqu’un qui s’en sert déjà.',
    'hp.v1.s2': "À choisir quand la plupart des arrivants sont des inconnus. Elle argumente : hero, pourquoi, comment ça marche, l'espace dev, les commandes, les avis, les actus, dans cet ordre, et il faut tout dérouler pour la lire.",
    'hp.v2.s2': "À choisir quand les gens arrivent en sachant ce qu'ils veulent. Elle répond : les quatre produits en liste avec le média à côté, les titres d'actus, puis la demande. Pas d'histoire, rien à lire sous la ligne de flottaison.",
    'hp.v3.s2': "À choisir quand la plupart des arrivants sont déjà venus. Elle raconte l'actualité : les articles en fil, avec le sondage en cours, les avis, ce qui est proposé et la vitrine à côté. Pas de hero, puisqu'ils savent ce qu'est le site.",
