    'bm.sort.name': 'Nom (A–Z)',
    'bm.sort.newest': 'Membres les plus récents',
    'bm.sort.oldest': 'Les plus anciens',
    'bm.sort.quiet': 'Silencieux depuis le plus longtemps',
    'bm.sort.recent': 'Actifs récemment',
    'hs.d.features.oauthLoginEnabled': 'Désactivé = ces boutons disparaissent et les deux moitiés du parcours refusent, y compris un retour déjà en cours. La connexion par mot de passe n’est pas touchée, donc ceci ne peut jamais vous enfermer dehors de cette page.',
    'hs.d.features.paymentsEnabled': 'Désactivé = aucun nouveau paiement ne peut démarrer nulle part : hébergement, catalogue, mises en avant, MYO. Les abonnements existants ne sont PAS annulés et le webhook Stripe continue de tourner, donc renouvellements et résiliations restent enregistrés. Couper ceci arrête les rentrées d’argent, cela n’abandonne pas les clients déjà là.',
    'hs.d.features.publicApiEnabled': 'Désactivé = toutes les routes à clé d’API répondent 503, y compris celles en lecture seule. Le site lui-même n’est pas affecté ; ceci ne gouverne que les clés tierces.',
    'hs.d.features.ssoEnabled': 'Désactivé = /oauth2/authorize et /oauth2/token refusent, donc les applications ne peuvent plus connecter les gens avec un compte BetterCommunity. Différent du réglage ci-dessus : celui-là, c’est nous qui UTILISONS GitHub/Discord ; celui-ci, c’est d’autres applications qui NOUS utilisent.',
    'hs.d.features.webhooksEnabled': 'Désactivé = les pourboires Ko-fi et les événements de push de dépôt sont refusés avec 503. Le webhook Stripe est délibérément EXCLU : couper celui-là ferait dériver la base de facturation par rapport à Stripe.',
    'hs.d.hosting.apiRateLimitMax': 'Au-delà, une IP reçoit 429 pour le reste de la minute, et après 4 refus elle est bloquée net avec 403 jusqu’à la fin de la fenêtre. 600 est généreux pour une personne (~10/s) ; baissez-le pendant que quelque chose martelène le site, augmentez-le si du vrai trafic est refusé. Borné à 30-100000 : vide ou 0 signifie la valeur par défaut RATE_LIMIT_MAX. Effectif en ~15 s, sans redémarrage.',
    'hs.d.hosting.rejectedRetentionDays': 'Combien de temps une soumission refusée conserve son fichier avant que le balayeur ne le purge pour récupérer de l’espace temporaire. L’auteur peut encore corriger et resoumettre pendant ce délai. 7 par défaut.',
    'hs.l.features.oauthLoginEnabled': 'Connexion avec GitHub / Discord / Google',
    'hs.l.features.paymentsEnabled': 'Paiements (Stripe) activés',
    'hs.l.features.publicApiEnabled': 'API publique (/v1) activée',
    'hs.l.seo.gtmOn': "Google Tag activé",
    'hs.d.seo.gtmOn': "Interrupteur principal pour Google Tag Manager / GA4. Le tag ne se charge TOUJOURS qu'après l'acceptation de la catégorie de cookies Analytics : cet interrupteur décide s'il est proposé, jamais si le consentement est nécessaire.",
    'hs.l.seo.gtmId': "Identifiant Google Tag",
    'hs.d.seo.gtmId': "GTM-XXXXXXX pour un conteneur Tag Manager, ou G-XXXXXXXXXX pour un identifiant de mesure GA4. Les deux sont acceptés et chargés correctement : donner un id G- au script de conteneur échoue en silence, d'où la vérification à l'enregistrement.",
    'hs.l.seo.googleVerify': "Jeton Google Search Console",
    'hs.d.seo.googleVerify': "La chaîne de vérification que Google vous donne (le contenu de sa balise meta, pas la balise entière). Sans elle la propriété ne peut pas être vérifiée : impossible de soumettre le sitemap ou de voir quoi que ce soit sur l'indexation. C'est la première étape pour exister dans Google.",
    'hs.l.seo.bingVerify': "Jeton Bing Webmaster",
    'hs.d.seo.bingVerify': "Même idée pour Bing, qui est aussi la source des résultats de DuckDuckGo.",
    'hs.l.seo.title': "Titre du site (EN)",
    'hs.d.seo.title': "Le titre en gras d'un résultat de recherche et de chaque lien partagé. Vide = nom intégré conservé. Visible dans la carte d'aperçu ci-dessous.",
    'hs.l.seo.titleFr': "Titre du site (FR)",
    'hs.d.seo.titleFr': "Le même, affiché quand le visiteur est sur le site français. Vide = retour à l'anglais.",
    'hs.l.seo.description': "Description du site (EN)",
    'hs.d.seo.description': "La phrase qu'affichent un résultat de recherche et chaque lien partagé. Environ 150 caractères sont réellement montrés ; au-delà c'est coupé en plein mot. Vide = texte intégré conservé.",
    'hs.l.seo.descriptionFr': "Description du site (FR)",
    'hs.d.seo.descriptionFr': "La même, affichée quand le visiteur est sur le site français. Vide = retour à la version anglaise.",
    'hs.l.seo.ogImage': "Image d'aperçu des liens",
    'hs.d.seo.ogImage': "L'image montrée quand le site est partagé sur Discord, X ou ailleurs. 1200x630 est la taille vers laquelle tout recadre. Vide = pas d'image, le lien s'affiche en texte simple.",
    'hs.l.features.ssoEnabled': 'Authentification unique (nous sommes le fournisseur d’identité)',
