    'ch.title': 'Cagnotte solidaire', 'ch.sub': 'Une association choisie par la communauté, chaque mois.',
    'ch.sub2': 'Une part de nos revenus est ajoutée à vos dons, et la cagnotte entière part à l’association que le vote désigne. Le versement est fait à la main, avec une preuve.',
    'ch.give.cta': 'Augmenter la cagnotte', 'ch.vote': 'Voter', 'ch.more': 'En savoir plus',
    'ch.breakdown': 'BetterCommunity {a} + communauté {b}', 'ch.community': 'communauté',
    'ch.for': 'Association du mois :', 'ch.voting': 'L’association est en cours de choix par vote communautaire.',
    'ch.projected': 'Jusqu’à {n} % des revenus mensuels éligibles sont ajoutés par BetterCommunity.',
    'ch.give.t': 'Augmenter la cagnotte', 'ch.give.s': 'Votre don est ajouté à la cagnotte du mois, aux côtés de la contribution de BetterCommunity, et reversé à l’association choisie.',
    'ch.custom': 'Ou un montant personnalisé', 'ch.total': 'Vous donnez', 'ch.confirm': 'Confirmer et payer',
    'ch.securenote': 'Vous confirmerez sur une page de paiement sécurisée. Rien n’est débité avant.',
    'ch.fee': 'Frais de carte estimés', 'ch.net': 'Arrive dans la cagnotte',
    'ch.feewhy': 'Le traitement par carte (Stripe) prélève environ {p}% + {f} par don, donc un peu moins que ce que vous donnez arrive dans la cagnotte. La cagnotte est créditée du montant exact des frais une fois payé, ce qui peut différer d’un centime ou deux de cette estimation.',
    'ch.securenote2': 'Vous confirmerez sur une page de paiement sécurisée. Rien n’est débité avant, et les dons sont définitifs : ils ne sont pas remboursables.',
    'ch.min': 'Le don minimum est de 1.00.', 'ch.off': 'La cagnotte n’est pas ouverte pour le moment.', 'ch.nostripe': 'Les paiements ne sont pas disponibles pour le moment.',
    'ch.page.intro': 'Chaque mois, une part des revenus éligibles de BetterCommunity (plus les dons volontaires de la communauté) est mise en commun et reversée à une association pour laquelle la communauté Discord vote.',
    'ch.page.off': 'Le programme solidaire n’est pas actif pour le moment. Revenez bientôt.',
    'ch.how.t': 'Comment ça marche',
    'ch.how.1': 'Chaque mois, BetterCommunity met de côté un pourcentage (jusqu’à 50 %) de ses revenus récurrents éligibles, ce qui reste après les coûts récurrents.',
    'ch.how.2': 'Vous pouvez alimenter la cagnotte à tout moment. Vos dons et la part de BetterCommunity sont suivis comme deux montants distincts et affichés ensemble dans une seule cagnotte.',
    'ch.how.3': 'La communauté vote pour l’association qui recevra la cagnotte du mois.',
