    'ch.voteclosed': 'vote clos',
    'chc.title': 'Cagnotte solidaire', 'chc.sub': 'Chaque mois, une part des revenus éligibles est reversée à une association choisie par la communauté. Le paiement final est envoyé manuellement.',
    'chc.design.t': 'Design de la page d’accueil', 'chc.design.sub': 'Rends la carte solidaire unique : choisis la taille du cadre, dessine le visuel aux tailles de canevas indiquées ci-dessous, importe chaque calque. Le calque de débordement peut sortir du cadre ; le sticker dépasse d’un coin. L’aperçu est exactement la carte affichée sur l’accueil.',
