    'fb.oldest': 'Plus vieux non trié', 'fb.cfg.limits2': 'Limites du point de retours (tous projets)', 'fb.cfg.limits.d2': 'Combien de rapports le point de retours accepte. Les plafonds API globaux (toutes les routes, par IP et par compte) sont sur l’écran API publique → Limites ; la rétention des pièces jointes dans Réglages d’hébergement → Stockage des retours.',
