    'chc.design.mode.custom.h2': 'Ton propre fond, un calque de débordement et un sticker de coin. Et maintenant : retirer n’importe quel élément de la carte, réécrire les libellés, ajouter ton CSS.', 'chc.design.mode.code': 'Tout écrire toi-même', 'chc.design.mode.code.h': 'Plus aucune carte dessinée par le site : tu choisis les blocs, leur ordre, et tu les mets en forme avec ton propre CSS, confiné à la carte.',
    'chc.part.icon': 'Icône cœur', 'chc.part.title': 'Titre', 'chc.part.sub': 'Accroche', 'chc.part.month': 'Pastille du mois', 'chc.part.amount': 'Montant total', 'chc.part.breakdown': 'Ligne de répartition', 'chc.part.bar': 'Barre de progression', 'chc.part.association': 'Ligne de l’association', 'chc.part.poll': 'Ligne du vote', 'chc.part.projected': 'Ligne de la part prévue', 'chc.part.paid': 'Avis « don envoyé »', 'chc.part.give': 'Bouton Donner', 'chc.part.vote': 'Bouton Voter', 'chc.part.more': 'Bouton En savoir plus',
