    'chc.design.grp.parts': 'Éléments : décoche ce que tu ne veux pas', 'chc.design.grp.words': 'Textes', 'chc.design.words.h': 'Laisse une case vide pour garder le texte traduit du site. Ce que tu écris ici s’affiche tel quel, dans toutes les langues.',
    'chc.design.grp.css': 'Ta feuille de style', 'chc.design.css.h': 'Chaque sélecteur que tu écris est confiné à cette carte : il ne peut pas restyler le reste du site. Vise .chy-card, .chy-content, .chy-title, .chy-amount… ou [data-el="amount"] et [data-b="…"] pour un bloc précis. @import, expression(), behavior et tout url() pointant hors du site sont refusés. Les classes Tailwind ne marchent que si le build du site les contient déjà : préfère du CSS simple ici.', 'chc.design.css.h2': 'Chaque sélecteur que tu écris est confiné à cette carte.', 'chc.design.css.refused': 'Laissé de côté :',
    'chc.design.cls.root': 'Classes : extérieur', 'chc.design.cls.card': 'Classes : carte', 'chc.design.cls.content': 'Classes : contenu',
    'chc.design.grp.blocks': 'Blocs : la carte, dans l’ordre', 'chc.design.blocks.h': 'N’ajoute que les morceaux que tu veux et ordonne-les toi-même. Chaque bloc a une case de classes et une prise [data-b] que ta feuille de style peut viser. Ton texte est affiché comme du texte, jamais comme du HTML.', 'chc.design.blocks.empty': 'Aucun bloc : la carte ne dessine rien du tout.', 'chc.design.blocks.add': 'Ajouter un bloc',
    'seoh.gtm': 'Google Tag Manager', 'seoh.gtm.env': 'Depuis le build (VITE_GTM_ID)', 'seoh.gtm.saved': 'Enregistré ici, chargé après consentement', 'seoh.gtm.no': 'Pas d’id de conteneur, renseigne-le ci-dessous', 'seoh.tags': 'Tag Manager & jetons de propriété, à régler ici', 'seoh.gtm.on': 'Charger le tag (après consentement analytique)', 'seoh.tags.d': 'La valeur d’environnement VITE_GTM_ID, si elle est fixée au build, l’emporte sur l’id enregistré ici. Les jetons sont le contenu de la balise meta demandée par la console, pas la balise entière.',
    'sm.title': 'Plan du site', 'sm.n': '{n} URL', 'sm.open': 'Ouvrir sitemap.xml', 'sm.sub': 'Construit en direct depuis le contenu publié : projets, articles, docs, éléments de catalogue et pages fixes. Ajoute un chemin que le routeur sert mais que cette liste ne peut pas connaître, ou retires-en un. Un par ligne.', 'sm.extra': 'Lister aussi', 'sm.exclude': 'Laisser de côté', 'sm.note': 'Les moteurs relisent le fichier à leur rythme ; rien à soumettre à la main.', 'sm.robots': 'robots.txt, règles supplémentaires', 'sm.robots.h': 'Ajoutées après les règles intégrées (les écrans privés restent interdits, le sitemap reste annoncé). Une directive par ligne, ex. « Disallow: /beta » ou « Crawl-delay: 5 ».',
    'fbs.title': 'Stockage des retours', 'fbs.open': 'Ouvrir le centre de retours', 'fbs.sub': 'Captures, journaux et zips de plantage envoyés avec les rapports. Ils vivent dans le stockage objet sous {p} et ne sont servis qu’au staff.', 'fbs.usage': 'En stockage', 'fbs.files': 'fichiers', 'fbs.rows': 'Rapports', 'fbs.closed': 'fermés', 'fbs.sweep': 'Balayage', 'fbs.hourly': 'toutes les heures',
