    'hs.seo.section': 'Moteurs de recherche, stockage des retours, seeds', 'sg.all': 'Tout sélectionner', 'sg.none': 'Aucun', 'sg.total': '{n} sections · {k} éléments',
    'afoot.status.none': 'Aucun service n’est encore surveillé: Serveur → Page de statut.', 'afoot.status.pick': 'Les services en surbrillance sont ceux que la ligne lit ; aucun en surbrillance = tous.', 'afoot.status.line': 'Une phrase', 'afoot.status.dots': 'Un point par service',
    'aapi.tab.limits': 'Limites', 'aapi.lim.title': 'Plafonds de requêtes', 'aapi.lim.sub': 'Combien de requêtes par minute la plateforme répond pour une IP et pour un compte connecté, sur toutes les routes. Le défaut par IP vient de l’environnement ({n}) ; 0 le garde. Par compte est désactivé à 0. Les deux prennent effet sous 15 secondes.', 'aapi.lim.ip': 'Requêtes / min par IP', 'aapi.lim.acct': 'Requêtes / min par compte', 'aapi.lim.429': 'Limitées (24 h)', 'aapi.lim.403': 'Interdites (24 h)', 'aapi.lim.fb': 'Le point de retours a ses propres limites, plus petites: Modération → Retours & plantages → Réglages du projet.',
    'dvt.dc.title': 'Vérifier un document', 'dvt.dc.s': 'Colle du B.MD et obtiens son plan plus chaque lien jugé : ancres contre les titres, URL refusées ou non sécurisées, destinations vides. Rien n’est téléchargé : la même vérification que l’éditeur fait pendant que tu tapes.', 'dvt.dc.h': '{n} titres', 'dvt.dc.l': '{n} liens', 'dvt.dc.issues': '{n} problème(s)', 'dvt.dc.ok': 'chaque lien mène quelque part',
