    'chc.design.grp.layers': 'Calques', 'chc.design.grp.frame': 'Cadre', 'chc.design.grp.place': 'Placement', 'chc.design.overflow.h2': 'Image transparente posée par-dessus le cadre, qui peut en sortir : une mascotte qui se penche, un ruban, des confettis. Laisse le centre libre : le texte est au-dessus.', 'chc.design.bleedof': '{n} px de débordement de chaque côté',
