    'adpay.title': 'Paiements en attente', 'adpay.run': 'Réconcilier maintenant', 'adpay.run.h': 'Demande à Stripe l’état de chaque paiement ouvert depuis plus de 15 minutes et termine ce que le webhook a manqué.', 'adpay.runall': 'Inclure les récents', 'adpay.runall.h': 'Pareil, y compris les paiements ouverts il y a quelques secondes. À utiliser quand tu sais que le webhook était en panne.',
    'adpay.sub': 'Chaque paiement Stripe est inscrit ici à l’ouverture et terminé par le webhook. Une ligne qui reste ouverte après paiement veut dire que le webhook n’a jamais tourné ; le réconciliateur (au démarrage, toutes les dix minutes, ou le bouton) interroge Stripe et livre ce qui a été payé. Les cas payés-non-livrés lèvent aussi une alerte sur la page Erreurs et préviennent les super-admins.',
