    'atask.team.none.t': "Aucune équipe interne pour l'instant",
    'atask.team.none.s': "Une équipe regroupe les personnes qui traitent le même genre de sujet, et leur donne un chef qui répartit le travail.",
    'atask.team.none.h': "Un administrateur les crée.",
    'atask.team.f.chief.h2': "La personne qui répartit le travail de cette équipe. Elle est ajoutée comme membre automatiquement. Cherchez par nom, e-mail ou identifiant.",
    'atask.team.f.chief.ph2': "Chercher le chef…",
