    'atask.team.chief.t': "Changer le chef",
    'atask.team.chief.m': "Le nouveau chef est ajouté à l'équipe s'il n'y est pas encore, et il est prévenu. L'ancien chef reste membre : retirez-le séparément si c'est ce que vous voulez.",
    'atask.team.chief.now': "Chef aujourd'hui",
    'atask.team.chief.next': "Nouveau chef",
    'atask.team.readonly': "Vous voyez les équipes et, là où vous êtes chef, vous gérez vos propres membres. Créer une équipe, la dissoudre et nommer un chef sont réservés aux administrateurs.",
    'atask.team.e.forbidden': "Votre compte n'a pas le droit de modifier les équipes. Créer, dissoudre et nommer un chef sont réservés aux administrateurs : demandez à un administrateur.",
    'atask.team.e.chief': "Plus aucun compte avec cet identifiant. Cherchez la personne et choisissez-la dans la liste.",
