    'atask.team.403.t': "Pas le droit de voir les équipes",
    'atask.team.403.s': "Ce tableau est réservé au staff. Demandez l'accès à un administrateur.",
    'atask.team.err.t': "Les équipes ne se sont pas chargées",
    'atask.team.err.s': "Rien n'a été modifié. Réessayez, et vérifiez que l'API répond.",
    'atask.team.x.s': "Une équipe a des membres et exactement un chef.",
    'atask.team.x.1': "Le chef répartit le travail de l'équipe : il peut affecter n'importe quelle tâche de l'équipe à n'importe lequel de ses membres, la reprendre, changer sa priorité et la fermer. Il peut ajouter et retirer des membres. Il ne peut ni créer une équipe, ni en dissoudre une, ni nommer un chef.",
    'atask.team.x.2': "Un administrateur fait tout cela, sur toutes les équipes, et il est le seul à pouvoir déplacer une tâche d'une équipe à une autre.",
    'atask.team.x.3': "Quand quelqu'un quitte une équipe, ses tâches inachevées retournent dans la file de l'équipe sans personne affectée et le chef en est informé. Les tâches déjà terminées gardent son nom : l'historique dit qui a fait le travail et n'est jamais réécrit.",
    // Tableau des tâches, second passage (23 sept.) : plusieurs personnes par tâche, liens,
    // propositions du site, équipes lisibles d'un coup d'œil, permissions fines.
    'atask.x.s2': "Les tâches sont confiées à une ou plusieurs personnes, par un répartiteur ou par le chef de leur équipe.",
    'atask.x.2b': "Les personnes sur une tâche la font avancer d'état en état, et chacune peut toujours s'en retirer. Y mettre quelqu'un d'autre est la décision du chef dans son équipe, et d'un répartiteur partout. Une tâche peut en attendre une autre (bloquée par), en bloquer une, ou simplement y être liée.",
    'atask.rules.1b': "Les personnes sur une tâche la font avancer d'état en état, et chacune peut toujours s'en retirer. Elles ne peuvent pas y mettre quelqu'un d'autre, ni l'annuler.",
    'atask.rules.2b': "Le chef d'équipe répartit le travail dans sa propre équipe, change la priorité et l'échéance, ferme ou annule. Un répartiteur fait tout cela dans toutes les équipes et peut déplacer une tâche d'une équipe à une autre. Supprimer une tâche pour de bon est réservé aux admins.",
    'atask.view.proposals': "Propositions",
