    'atask.link.e.dup': "Ces deux tâches sont déjà liées de cette façon.",
    'atask.sg.x.s': "Des tâches que le site propose à partir de son propre état. Rien ne devient une tâche tant que quelqu'un ne l'accepte pas.",
    'atask.sg.x.1': "Quatre sources sont lues : un service en panne sur la page de statut, une file « À traiter » où du travail attend, une alerte serveur ouverte, et un groupe d'erreurs des dernières 24 heures. Un incident donne une seule proposition, quel que soit le nombre de fois où il est vu ; son compteur monte à la place.",
    'atask.sg.x.2': "Le texte est nettoyé avant d'être enregistré : chaque lien, chemin, clé et adresse est remplacé, et une file ne liste jamais ses éléments. C'est ce qui permet de l'accepter sans risque dans une tâche que toute l'équipe lit. La source elle-même reste à un clic, derrière sa propre permission.",
    'atask.sg.x.3': "Vous ne voyez que les propositions issues de sources que vous pouvez déjà lire. En écarter une la cache une semaine ; si le problème est toujours là ensuite, elle revient une fois.",
