    'atask.sg.none.s': "Aucun service en panne, aucune file en attente, aucune alerte ni groupe d'erreurs ouvert, parmi les sources que vous pouvez lire.",
    'atask.sg.hidden': "{n} autre(s) viennent de sources que votre compte ne peut pas lire.",
    'atask.sg.403.t': "Les propositions sont pour les répartiteurs",
    'atask.sg.403.s': "Examiner ce que le site propose demande la permission « Répartir les tâches ».",
    'atask.team.x.1b': "Le chef répartit le travail de l'équipe : il peut mettre n'importe quel membre de l'équipe sur n'importe laquelle de ses tâches, l'en retirer, changer la priorité et fermer une tâche. Il ajoute des membres du staff à l'équipe et en retire. Il ne peut ni créer ni dissoudre une équipe, ni nommer un chef.",
    'atask.team.x.2b': "Trois permissions se placent au-dessus. « Voir toutes les tâches » lit tout le tableau. « Répartir les tâches » fait ce que fait un chef, dans toutes les équipes. « Organiser les équipes du staff » crée, renomme, archive et dissout les équipes. Nommer un chef ou ajouter des membres, c'est confier un pouvoir, donc il faut aussi « Répartir les tâches » : personne ne peut donner ce qu'il n'a pas.",
    'atask.team.readonly2': "Vous voyez les équipes et, là où vous êtes chef, vous gérez vos membres. Créer une équipe demande « Organiser les équipes du staff » et « Répartir les tâches ».",
