    'atask.team.e.namechief': "Nommer un chef, c'est confier le droit de répartir : il faut donc à la fois « Organiser les équipes du staff » et « Répartir les tâches ». Personne en dessous d'admin ne peut se nommer lui-même.",
    'atask.team.e.addmember': "Vous ne pouvez pas ajouter cette personne. Un chef ajoute des personnes qui font déjà partie du staff ; faire entrer quelqu'un de nouveau sur le tableau, ou s'ajouter soi-même, demande davantage.",
