    'hp.preview': 'Prévisualiser mes modifications',
    'hp.preview.t': 'Ta page d’accueil, non enregistrée',
    'hp.preview.s': 'Les textes et les interrupteurs de sections sont les tiens tels quels. Les articles, statistiques, avis et la vitrine sont en direct : un aperçu de textes ne doit pas inventer le contenu autour.',
    'home.mod.official': 'Le catalogue officiel',
    'home.mod.official.d': 'Vérifié avant d’apparaître. Un envoi reste invisible tant qu’une personne de l’équipe ne l’a pas ouvert et approuvé, et un refus est motivé.',
    'home.mod.community': 'Catalogues et dépôts de la communauté',
    'home.mod.community.d': 'Publié par son auteur, tout de suite. Chaque fiche affiche le compte qui l’a mise en ligne, n’importe qui peut signaler un problème, et nous suspendons ce qui enfreint les règles. Vérifié après publication, et signalé comme tel partout où il apparaît.',
    'home.mod.self': 'Publié par son propriétaire',
    'home.mod.reported': 'Signalable',
    'home.mod.suspended': 'Suspendu',
    'sec.rb.what': 'Ce que ça veut dire',
    'sec.rb.content': 'Le contenu d’une ligne ne correspond plus à sa signature. Quelqu’un a modifié une entrée directement en base : le journal contient la version modifiée, et l’originale a disparu sauf si une sauvegarde la détient.',
    'sec.rb.chain': 'Chaque ligne se signe encore correctement, mais l’une d’elles ne pointe plus vers celle d’avant. Des entrées ont été supprimées ou insérées au milieu. Rien ne dit CE qui a été retiré, seulement que le compte a changé.',
    'sec.rb.trunc': 'Une entrée écrite sur le volume d’ancrage externe manque en base, et elle est plus récente que la fenêtre de rétention : elle n’a donc pas été purgée. Les lignes les plus récentes ont été supprimées : la seule altération que la chaîne en base ne peut pas voir seule.',
    'sec.rb.anchored': 'L’entrée d’une action sensible diffère de la copie ancrée hors base au moment où elle a eu lieu. L’ancre est l’enregistrement antérieur, et non compromis.',
    'sec.rb.generic': 'La chaîne ne se vérifie plus. Traitez chaque entrée à partir de la cassure comme invérifiable, dans les deux sens.',
    'sec.rb.key': 'Le secret de signature vit dans l’environnement du serveur, pas en base. Une chaîne forgée qui se vérifierait voudrait dire que ce secret a fuité aussi. Une cassure signifie donc en général un accès à la base, et pas à la clé.',
    'sec.rb.do': 'Quoi faire, dans cet ordre',
    'sec.tool.export': 'Exporter le dossier de preuve',
    'sec.tool.export.d': 'La cassure, les lignes de part et d’autre, et chaque ancre externe, signés avec la clé du site pour qu’on puisse démontrer qu’ils viennent d’ici sans retouche. Enregistrez-le là où ce serveur ne peut pas écrire.',
    'sec.tool.export.ok': 'Exporté.',
    'sec.tool.exported': 'Preuve exportée. Gardez-la là où ce serveur ne peut pas aller.',
    'sec.tool.anchor': 'Ancrer la tête du journal maintenant',
    'sec.tool.anchor.d': 'Écrit l’empreinte de l’entrée la plus récente sur le volume d’ancrage, hors base. Seules les actions sensibles s’ancrent d’elles-mêmes : un journal ordinaire n’a donc rien à quoi se comparer. Après ça, supprimer les lignes les plus récentes devient détectable.',
    'sec.tool.anchor.d2': 'Écrire l’empreinte de l’entrée la plus récente hors base, pour que la suppression des lignes récentes devienne détectable.',
    'sec.tool.anchor2': 'Ancrer maintenant',
    'sec.tool.anchored': 'Tête ancrée hors de la base.',
    'sec.tool.nohead': 'Rien de signé à ancrer pour l’instant.',
    'sec.tool.resealbtn': 'Re-signer à partir de la cassure',
    'sec.tool.reseal.d': 'En dernier, et seulement une fois le dossier enregistré. Ça rétablit la détection pour la suite ; ça ne rétablit pas la confiance dans les entrées re-signées, et ça écrase la preuve que la cassure a eu lieu. Superadmin, et élévation requise.',
    'sec.tool.reseal.t': 'Re-signer le journal à partir de la cassure ?',
    'sec.tool.reseal.b': 'La chaîne se vérifiera de nouveau et la PROCHAINE altération sera détectable. Les entrées re-signées ne deviennent pas fiables pour autant (leur contenu est ce que la base contient maintenant) et la preuve que la cassure a existé est écrasée. Exportez le dossier d’abord.',
    'sec.tool.reseal.go': 'Re-signer',
    'sec.tool.resealed': 'Re-signées',
    'sec.tool.needexport': 'Exportez d’abord le dossier de preuve, re-signer le détruit.',
    'sec.tool.nobreak': 'La chaîne se vérifie. Rien à re-signer.',
