    'al.mng.cats': 'Rubriques',
    'al.mng.cats.d': 'Ce sous quoi l’index regroupe les documents, une par projet, en général. Un document sans rubrique est listé seul, au-dessus. La clé est une ancre : /legal#bmm.',
    'al.mng.add': 'Nouveau',
