    'scn.hv.fracture': 'Éclats',
    'scn.hv.fracture.d': 'Elle se brise en ses propres faces et vole en éclats. Ce que le site a toujours fait : conçu pour l’orbe, alors essayez-le sur la forme que vous avez choisie.',
    'scn.hv.swell': 'Gonflement',
