    'scn.reveal': 'Comment les sections arrivent',
    'scn.reveal.d': 'S’applique à toutes les pages, y compris celles où la scène n’est pas dessinée. Rechargez pour la voir.',
    'scn.rv.rise': 'Montée',
    'scn.rv.rise.d': 'Se soulève en place, en rétrécissant un peu, avec un flou qui se lève. Celle d’origine.',
    'scn.rv.fade': 'Fondu',
    'scn.rv.fade.d': 'L’opacité seule, rien ne semble bouger.',
