    'scn.rv.none': 'Aucune',
    'scn.rv.none.d': 'Les sections sont simplement là.',
    'scn.prev.d2': 'La vraie : même géométrie, même shader, même palette que la page derrière vous. Survolez-la pour essayer la réaction au pointeur. Seuls l’intro, la parallaxe du curseur et la dérive au défilement sont laissés de côté.',
    'assets.drop': 'Déposez des fichiers ici',
    'assets.drop.d': 'N’importe quel type. La clé vient du nom du fichier, et un nom déjà pris reçoit un numéro plutôt que de remplacer ce qui est là.',
    'assets.choose': 'Choisir des fichiers',
    'assets.uploadedN': '{n} fichier(s) envoyé(s).',
    'assets.search': 'Chercher par nom…',
    'assets.all': 'Tout',
    'assets.nomatch': 'Rien ne correspond',
    'assets.lib.none': 'Rien d’envoyé pour l’instant',
    'assets.lib.none.s': 'Déposez des fichiers au-dessus, images, vidéos, sons, n’importe quoi.',
    'assets.noinline': 'Ce type n’est pas affiché dans le navigateur, il est servi en téléchargement, volontairement.',
    'assets.count.on': 'Compter les vues et les téléchargements',
