    'assets.k.other': 'Autres',
    'scn.title': 'Scène 3D',
    'scn.desc': 'La forme WebGL derrière chaque page. Un visiteur peut toujours la désactiver pour lui-même, et elle n’est jamais dessinée sur une machine sans GPU fonctionnel : ceci décide de ce qu’elle dessine quand elle l’est.',
    'scn.orb': 'Orbe',
    'scn.orb.d': 'Une sphère déformée. Ce que le site a toujours dessiné.',
    'scn.prism': 'Prisme',
    'scn.prism.d': 'Quatre faces planes. La silhouette la plus anguleuse ici, et la moins coûteuse à dessiner.',
    'scn.crystal': 'Cristal',
    'scn.crystal.d': 'Huit faces. Assez grandes pour que la déformation se voie à l’intérieur d’une seule : la forme à prendre quand c’est la surface qui travaille.',
    'scn.gem': 'Gemme',
    'scn.gem.d': 'Douze pentagones. Le plus de facettes avant que le contour ne redevienne une sphère ; à son avantage avec la déformation baissée.',
    'scn.ring': 'Nœud',
    'scn.ring.d': 'Un tore noué. Le plus de mouvement et le plus de remplissage, baissez le détail sur une machine lente.',
    'scn.halo': 'Halo',
    'scn.halo.d': 'Un anneau simple. L’idée du nœud avec un seul trou et un contour net, ce que demande une page chargée de texte devant.',
    'scn.cube': 'Cube',
    'scn.cube.d': 'Six carrés plats et des angles droits. La seule forme ici qui ait un coin, et celle qui se lit comme construite plutôt que poussée.',
    'scn.spire': 'Flèche',
    'scn.spire.d': 'Une pointe sur une base large. Plus haute que large, c’est donc celle qui change l’équilibre de la page.',
    'scn.capsule': 'Capsule',
    'scn.capsule.d': 'Une gélule : bouts arrondis, flancs droits, aucune facette. Celle à choisir quand la distorsion est poussée.',
    'scn.spiral': 'Spirale',
    'scn.spiral.d': 'Un tube enroulé en tonneau. Plus de vide que de surface, et elle se lit comme un mouvement même à l’arrêt. La plus lourde à dessiner après le nœud.',
    'scn.vase': 'Vase',
    'scn.vase.d': 'Un profil tourné au tour, avec une taille marquée. Une courbe qui rentre puis ressort, ce qu’aucune autre forme ne fait ici.',
    'scn.md.title': 'Vérifier un de vos modèles',
    'scn.md.d2': 'Un fichier glTF 2.0 binaire (.glb), jusqu’à 8 Mo. Il est lu sur cette machine uniquement : rien ne quitte cette page et rien n’est enregistré. L’import d’un modèle dans la scène n’est pas terminé, voici la moitié qui peut déjà vous dire si le vôtre serait accepté et ce qu’il coûterait à dessiner.',
    'scn.md.pick': 'Choisir un .glb',
    'scn.md.tris': '{a} triangles, dessinés en {b} morceaux.',
    'scn.md.gpu': '{a} Mo sur la carte graphique, pour un fichier de {b} Mo.',
    'scn.md.tex': '{a} Mo de ce fichier sont de la texture, et aucune ne servirait : la scène peint un modèle avec la couleur d’accent du site, pas avec ses propres matériaux.',
    'scn.md.ok': 'Dans toutes les limites.',
    'scn.md.w.tris': 'Plus lourd que toutes les formes intégrées. Il reste sous le plafond, et il coûterait plus que ce pour quoi la scène a été conçue.',
    'scn.md.w.draws': 'Plusieurs morceaux séparés. Chacun est un appel de dessin à chaque image, derrière chaque page.',
    'scn.md.w.tex': 'Plus de la moitié de ce fichier est une texture qui ne servirait jamais. Réexportez sans les textures et il se télécharge bien plus vite.',
    'scn.md.e.size': 'Trop gros : {a} Mo, le plafond est à {b} Mo. Un modèle est téléchargé avant que le décor puisse se dessiner, à chaque première visite.',
    'scn.md.e.glb': 'Ce n’est pas un fichier .glb. Exportez depuis votre outil 3D en glTF 2.0 binaire : un .gltf pointe vers sa géométrie et ses textures hors de lui-même, un .glb les porte.',
    'scn.md.e.ver': 'glTF version {a}. Seul glTF 2.0 est lu.',
    'scn.md.e.trunc': 'Le fichier annonce une longueur différente de la sienne. Tronqué ou corrompu, réexportez-le.',
    'scn.md.e.json': 'Le bloc de description à l’intérieur du fichier n’a pas pu être lu.',
    'scn.md.e.draco': 'Compressé avec Draco. Le lire demande un décodeur de 700 ko que nous n’envoyons pas à chaque visiteur. Réexportez sans la compression Draco.',
    'scn.md.e.ext': 'Utilise une extension que nous ne traitons pas : {a}. L’accepter quand même reviendrait à deviner ce qu’elle demande.',
    'scn.md.e.uri': 'Pointe vers un fichier hors de lui-même ({a}). Chaque visiteur irait le chercher sur chaque page. Réexportez avec tout intégré.',
    'scn.md.e.empty': 'Aucun triangle dedans. Les caméras, les lumières, l’animation et les maillages de points ou de lignes ne comptent pas, et il n’y avait rien d’autre.',
    'scn.md.e.draws': '{a} morceaux à dessiner, le plafond est à {b}. C’est en général une scène entière plutôt qu’un objet.',
    'scn.md.e.tris': '{a} triangles, le plafond est à {b}. La forme intégrée la plus lourde en fait 17 640, et le shader s’exécute sur chaque sommet de chaque image. Décimez-le dans l’outil qui l’a produit : nous ne le ferons pas mal à votre place.',
    'scn.on': 'Dessinée sur chaque page',
    'scn.off': 'Éteinte',
    'scn.surface': 'Surface',
    'scn.sf.solid': 'Pleine',
    'scn.sf.solid.d': 'Faces remplies.',
    'scn.sf.wire': 'Fil de fer',
    'scn.sf.wire.d': 'Les arêtes seules, la même surface, dessinée en lignes.',
    'scn.sf.both': 'Les deux',
    'scn.sf.both.d': 'Un fil de fer tracé par-dessus la surface pleine.',
    'scn.opacity': 'Présence',
    'scn.opacity.d': 'Quelle quantité de surface il y a. Ne descend jamais à 0, c’est l’interrupteur au-dessus, et il ne coûte rien au lieu de ne rien dessiner.',
    'scn.scale': 'Taille',
    'scn.scale.d': 'Multiplie le cadrage, pour que l’intro garde sa proportion avec la taille au repos.',
    'scn.glow': 'Halo',
    'scn.glow.d': 'La lumière douce derrière. À 0 elle n’est pas dessinée du tout.',
    'scn.tw': 'Poussière',
    'scn.tw.d': 'Des grains sur une ceinture inclinée qui orbite la forme, passant devant et derrière. 0 les enlève.',
    'scn.fps': 'Budget d’images', 'scn.fps.d': 'Images par seconde quand rien de rapide ne se passe. 30 rend pareil que 60 pour un fond qui dérive et coûte moitié moins de CPU ; l’intro et le survol restent à plein régime.',
    'scn.prev.d': 'La vraie : même géométrie, même shader, même palette que la page derrière vous. Seuls l’intro, la parallaxe du curseur et la dérive au défilement sont laissés de côté.',
    'scn.prev.off': 'Rien n’est dessiné. Les pages s’affichent exactement comme sur une machine sans WebGL, un chemin que le site a toujours dû savoir tenir.',
    'scn.detail': 'Détail',
    'scn.detail.d': 'Subdivisions. Le coût croît avec le carré de ce chiffre, et c’est un élément de fond, 4 est la valeur d’origine.',
    'scn.noise': 'Déformation',
    'scn.noise.d': 'À quel point la surface est poussée. 0 laisse le solide nu, ce qui est un look en soi.',
    'scn.speed': 'Vitesse',
    'scn.speed.d': 'Rotation et dérive. 0 l’arrête net, toujours dessinée, plus en mouvement.',
    'scn.reload': 'Rechargez la page pour la voir derrière vous, le fond est construit une fois, au chargement.',
    'scn.desc2': 'La forme WebGL derrière chaque page. Un visiteur peut toujours la désactiver pour lui-même. Là où WebGL ne peut pas tourner, ou pendant que le pilote graphique se rétablit, un dessin fixe de la même forme prend sa place.',
    'scn.g.shape': 'Forme',
    'scn.g.look': 'Aspect',
    'scn.g.motion': 'Mouvement',
    'scn.g.air': 'Autour',
    'scn.g.page': 'Page et performances',
    'scn.u.fps': '{n} ips',
    'scn.u.count': '{n} grains',
    'scn.default': 'défaut {v}',
    'scn.reset.one': 'Revenir à {v}',
    'scn.reset.all': 'Réglages d’origine',
    'scn.revert': 'Annuler les modifications',
    'scn.dirty': 'Modifications non enregistrées. Les visiteurs voient toujours la scène enregistrée.',
    'scn.clean': 'Enregistré. C’est ce que voient les visiteurs.',
    'scn.detail.d2': 'Subdivisions. Le coût croît avec le carré de ce chiffre. Les formes plates s’arrêtent plus tôt (prisme et cristal à 3, gemme à 2) : au-delà elles dessinent la même chose.',
